    /// <summary>True when <paramref name="path"/> (base-relative, no query) is one of the More pages or beneath one.</summary>
    public static bool Owns(string path)
    {
        path = path.Trim('/').ToLowerInvariant();
        foreach (var item in Items)
        {
            if (path == item.Href || path.StartsWith(item.Href + "/", StringComparison.Ordinal)) return true;
        }
        return false;
    }
